    31      inline
    32      std::string to_string(encoding_kind encoding)
    33      {
    34          switch (encoding)
    35          {
    36              case encoding_kind::utf8:
    37                  return "utf8";
    38              case encoding_kind::utf16le:
    39                  return "utf16le";
    40              case encoding_kind::utf16be:
    41                  return "utf16be";
    42              case encoding_kind::utf32le:
    43                  return "utf32le";
    44              case encoding_kind::utf32be:
    45                  return "utf32be";
    46              default:
    47                  return "undetected";
    48          }
    49      }
