    94      template <class Byte>
    95      typename std::enable_if<jsoncons::detail::is_byte<Byte>::value,detect_encoding_result<Byte>>::type
    96      detect_json_encoding(const Byte* data, std::size_t length)
    97      {
    98          detect_encoding_result<Byte> r = detect_encoding_from_bom(data,length);
    99          if (r.encoding != encoding_kind::undetected)
   100          {
   101              return r;
   102          }
   103          else if (length < 4)
   104          {
   105              return detect_encoding_result<Byte>{data,encoding_kind::utf8};
   106          }
   107          else if (*data == 0 && *(data+1) == 0 && *(data+2) == 0)
   108          {
   109              return detect_encoding_result<Byte>{data,encoding_kind::utf32be};
   110          }
   111          else if (*data == 0 && *(data+2) == 0)
   112          {
   113              return detect_encoding_result<Byte>{data,encoding_kind::utf16be};
   114          }
   115          else if (*(data+1) == 0 && *(data+2) == 0 && *(data+3) == 0)
   116          {
   117              return detect_encoding_result<Byte>{data,encoding_kind::utf32le};
   118          }
   119          else if (*(data+1) == 0 && *(data+3) == 0)
   120          {
   121              return detect_encoding_result<Byte>{data,encoding_kind::utf16le};
   122          }
   123          else
   124          {
   125              return detect_encoding_result<Byte>{data,encoding_kind::utf8};
   126          }
   127      }
