   216          expected_continuation_byte,  // expected continuation byte
   217          unpaired_high_surrogate,     // unpaired high surrogate UTF-16
   218          illegal_surrogate_value,     // UTF-16 surrogate values are illegal in UTF-32
   219          source_exhausted,            // partial character in source, but hit end
