   223      class Unicode_traits_error_category_impl_
   224         : public std::error_category
   225      {
   226      public:
   227          virtual const char* name() const noexcept
   228          {
   229              return "unicode_traits conversion error";
   230          }
   231          virtual std::string message(int ev) const
   232          {
   233              switch (static_cast<conv_errc>(ev))
   234              {
   235              case conv_errc::over_long_utf8_sequence:
   236                  return "Over long utf8 sequence";
   237              case conv_errc::expected_continuation_byte:
   238                  return "Expected continuation byte";
   239              case conv_errc::unpaired_high_surrogate:
   240                  return "Unpaired high surrogate UTF-16";
   241              case conv_errc::illegal_surrogate_value:
   242                  return "UTF-16 surrogate values are illegal in UTF-32";
   243              case conv_errc::source_exhausted:
   244                  return "Partial character in source, but hit end";
   245              case conv_errc::source_illegal:
   246                  return "Source sequence is illegal/malformed";
   247              default:
   248                  return "";
   249                  break;
   250              }
   251          }
   252      };
